import type { CreateTransportRequestInput } from '@deadspace/shared';
import type { PrismaClient } from '../db.js';
import type { Prisma, TransportRequest } from '../generated/prisma/client.js';

/** Maps validated input to columns. The *Geog columns are generated by the database. */
export function toTransportRequestCreateData(input: CreateTransportRequestInput): Prisma.TransportRequestCreateInput {
  const { pickup, dropoff, ...rest } = input;
  return {
    ...rest,
    pickupLabel: pickup.label,
    pickupLat: pickup.lat,
    pickupLng: pickup.lng,
    dropoffLabel: dropoff.label,
    dropoffLat: dropoff.lat,
    dropoffLng: dropoff.lng,
  };
}

export function createTransportRequest(
  prisma: PrismaClient,
  input: CreateTransportRequestInput,
): Promise<TransportRequest> {
  return prisma.transportRequest.create({ data: toTransportRequestCreateData(input) });
}
